 row(group,"Home wallpaper",WallpaperPack.name(this,false),()->appearance("home"));row(group,"App drawer wallpaper",drawerWallpaperName(),()->appearance("drawer"));toggle(group,"Glass cards","glass_cards",true);toggle(group,"Flip Home wallpaper","flip_gradients",false);toggle(group,"Dim after sunset","auto_dim",false);step(group,"Text size (%)","text",85,120,100,5);step(group,"Layout spacing","spacing",8,24,14,1);
 group=section("PERSONALIZATION");row(group,"Accent color",accentName(),()->chooseAccent());row(group,"Vehicle name",prefs.getString("brand_text","CIVIC"),()->editLabel("Vehicle name","brand_text","CIVIC"));row(group,"Trim badge",prefs.getString("badge_text","RS"),()->editLabel("Trim badge","badge_text","RS"));row(group,"Solar location",prefs.getBoolean("solar_manual",false)?"Manual":"Automatic location",()->editSolarLocation());
