 group=section("STARTUP");row(group,"Launch application",startupName(),()->{Intent i=new Intent(this,AppPickerActivity.class).putExtra(AppPickerActivity.ROLE,"startup").putExtra(AppPickerActivity.TARGET,prefs.getString("startup_app",""));startActivityForResult(i,PICK);});row(group,"Launch delay",startupDelayName(),()->chooseInt("Launch delay",new String[]{"5 seconds","10 seconds","20 seconds","30 seconds"},new int[]{5,10,20,30},"startup_delay",10));toggle(group,"Start in screensaver","startup_saver",false);row(group,"Initial audio source",startupSourceName(),()->chooseStartupSource());
